mapper.select:
SELECT event_id,device_key,model_key,model_version,occurred_at,received_at,properties_json FROM device_telemetry
WHERE device_key=#{deviceKey} AND occurred_at >= #{from} AND occurred_at < #{to}
  AND (occurred_at > #{afterTime} OR (occurred_at=#{afterTime} AND event_id > #{afterId}))
ORDER BY occurred_at,event_id LIMIT #{limit}
